/* V26: short decorative responses. No gameplay, storage or RNG changes. */
let cuteBusy=false,cutePending=[],cuteScene='',cuteTimer=null,cuteOwner=null;
function cuteSnapshot(s){return s?{phase:s.phase,step:s.step,cursor:s.cursor,sat:[...s.sat],energy:[...s.energy],set:s.set.length,performed:s.performed.length,encores:s.encores,hidden:s.hiddenSeen.length,incident:s.incident,challengeResult:s.challengeResult.map(r=>({...r})),meetingWho:s.phase==='prep'&&Game.step(s)?.type==='meeting'?Game.step(s).who:null}:null}
function cuteActionEvents(fn,args,a,b){if(!a||!b)return [];const e=[];if(a.step===b.step&&a.phase===b.phase&&a.cursor===b.cursor&&a.performed===b.performed&&a.encores===b.encores&&a.hidden===b.hidden&&a.sat.every((v,i)=>v===b.sat[i])&&a.energy.every((v,i)=>v===b.energy[i]))return e;
 if(['select','personal'].includes(fn)&&b.set>a.set)e.push({type:'song',text:'셋리 확정!',who:fn==='personal'?track(args[0])?.soloMember:undefined});
 if(fn==='meeting'&&a.step!==b.step&&args[0]<2)e.push({type:'agreement',who:a.meetingWho,other:memberMeetingPlan({set:[]},a.meetingWho).other,text:args[0]===0?'좋아, 같이 맞춰보자!':'이 정도면 같이 할 수 있겠어!'});
 if(fn==='rest'||fn==='directCue'&&args[0]==='talk'){if(b.energy.some((v,i)=>v>a.energy[i]))e.push({type:'water',text:'물 한 모금, 다시 힘내자!'})}
 if(b.challengeResult.length&&b.performed>a.performed&&b.challengeResult.some((r,i)=>r.result!==a.challengeResult[i]?.result||r.rating!==a.challengeResult[i]?.rating))e.push({type:'challenge',members:b.challengeResult,text:'오늘의 마지막 포즈!'});
 if(fn==='encore'&&b.encores>a.encores||fn==='fatigueChoice'&&args[0]===true&&b.phase==='result')e.push({type:'return',text:'우리 다시 나왔다!'});
 if(b.hidden>a.hidden)e.push({type:'hidden',text:'어? 여기 뭐가…'});
 if(!e.length){let who=0;for(let i=1;i<4;i++)if(Math.abs(b.sat[i]-a.sat[i])>Math.abs(b.sat[who]-a.sat[who]))who=i;const d=b.sat[who]-a.sat[who];if(d)e.push({type:d>0?'happy':'ponder',who,text:d>0?['♪ 좋아!','좋은데? ♡','이 소리 좋다 ✦','응, 준비됐어!'][who]:'…'})}
 return e}
function cuteSceneEvent(s){if(!s||s.phase==='result')return null;const f=s.phase==='prep'?Game.step(s):null;if(f?.type==='hidden')return {key:'hidden/'+f.key,type:'hidden',text:'어? 여기 뭐가…'};if(f?.type==='challenge'||s.phase==='live'&&s.queue[s.cursor]?.kind==='challenge')return {key:'ready/'+s.phase,type:'ready',text:'두근… 내 차례?!'};if(s.phase==='incident'&&s.incident==='choir')return {key:'choir',type:'choir',text:'왈왈이 목소리가 모이면 ♡'};if(s.phase==='encore'&&(Game.encoreGate(s)||Game.fatigueGate(s)))return {key:'encore',type:'encore',text:'앵콜! 한 번만 더!'};return null}
function cuteAllowed(){return stageEffects&&!(typeof historyReadOnly!=='undefined'&&historyReadOnly)&&!(typeof window.matchMedia==='function'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)}
function clearCute(){if(cuteTimer!==null){clearTimeout(cuteTimer);cuteTimer=null}document.querySelector('#cute-moment')?.remove();document.querySelectorAll?.('.cute-react').forEach(el=>{el.classList.remove('cute-react','cute-react-happy','cute-react-ponder','cute-react-water')})}
function cuteAnimal(who,mode='happy'){const m=MEMBER_MOTIFS[who],prop=['♪','♡','🎧',''][who];return `<span class="cute-pet cute-pet-${who} cute-pet-${mode}"><span class="cute-pet-face">${m.animal}</span>${prop?`<i class="cute-pet-prop">${prop}</i>`:'<svg class="cute-sticks" viewBox="0 0 40 30"><path d="M8 25 29 3M14 3l18 22"/></svg>'}</span>`}
function cuteEventHTML(e){let art='';if(e.type==='happy'||e.type==='ponder')art=cuteAnimal(e.who,e.type);if(e.type==='song')art='<span class="cute-stamp">SETLIST<br>✦ CONFIRMED</span><span class="cute-star-seal">✦</span>';if(e.type==='agreement')art=`<div class="cute-highfive">${cuteAnimal(e.who)}<span class="cute-five">✋</span>${cuteAnimal(e.other)}</div>`;if(['ready','return'].includes(e.type))art=`<div class="cute-roster">${[0,1,2,3].map(i=>cuteAnimal(i,e.type)).join('')}</div>`;if(e.type==='ready')art+='<span class="cute-shy">두근…</span>';if(e.type==='challenge')art=`<div class="cute-results">${e.members.map(r=>{const mode=['perfect','close'].includes(r.result)?'success':r.result==='recover'?'recover':'miss',word=mode==='success'?'✦ ✦ ✦':mode==='recover'?'아무튼 성공적…!':'다음엔 맞춰볼게…';return `<span class="cute-result cute-result-${mode}">${cuteAnimal(r.member,mode)}<small>${word}</small></span>`}).join('')}</div>`;if(e.type==='water')art='<svg class="cute-bottle" viewBox="0 0 40 55" aria-hidden="true"><rect x="13" y="2" width="14" height="7" rx="2" fill="#397faf"/><path d="M14 9v6l-6 8v25q0 4 4 4h16q4 0 4-4V23l-6-8V9Z" fill="#eef8fc" stroke="#72b0d5" stroke-width="2"/><path d="M9 32q6-5 11 0t11 0v16q0 3-4 3H13q-4 0-4-3Z" fill="#96cce8"/><path d="M20 25c-8 10-7 14 0 14s8-4 0-14" fill="#4b99c9"/></svg><span class="cute-drops"><i>💧</i><i>💧</i><i>💧</i></span>';if(e.type==='choir')art=`<div class="cute-choir">${['♡','♪','♡','♪','♡','♪'].map((x,i)=>`<i style="--n:${i}">${x}</i>`).join('')}<b>💙</b></div>`;if(e.type==='encore')art='<span class="cute-encore-notes"><i>앵콜!</i><i>한 번만 더!</i><i>앵콜!</i></span>';if(e.type==='hidden')art='<span class="cute-fold"><i>✦</i><b>작은 발견</b></span>';if(e.type==='ticket')art='<span class="cute-ticket-stamp">오늘도<br>함께 ♡</span>';return `<div class="cute-scene cute-scene-${e.type}">${art}<p>${esc(e.text)}</p></div>`}
function emitCute(events){if(!cuteAllowed()||!events.length||typeof document.createElement!=='function')return;clearCute();const el=document.createElement('aside');el.id='cute-moment';el.className='cute-moment';el.setAttribute('aria-hidden','true');el.innerHTML=events.slice(0,2).map(cuteEventHTML).join('');const dialog=document.querySelector('#modal');(dialog?.open?dialog:document.body).appendChild(el);for(const e of events){if(['happy','ponder'].includes(e.type)){const sticker=document.querySelector('.statuscard .membervoice-'+e.who+' .mood-sticker');sticker?.classList.add('cute-react','cute-react-'+e.type)}if(e.type==='water')document.querySelectorAll?.('.statuscard .bar.thin').forEach(x=>x.classList.add('cute-react','cute-react-water'))}cuteTimer=setTimeout(()=>{el.remove();document.querySelectorAll?.('.cute-react').forEach(x=>x.classList.remove('cute-react','cute-react-happy','cute-react-ponder','cute-react-water'));cuteTimer=null},events.some(e=>e.type==='challenge')?2600:1850)}
function syncCuteControls(){document.body?.classList?.toggle('effects-off',!stageEffects);const links=document.querySelector('.headlinks');if(links&&typeof document.createElement==='function'){let button=document.querySelector('#cute-effects-toggle');if(!button){button=document.createElement('button');button.id='cute-effects-toggle';button.setAttribute('onclick','toggleStageEffects(!stageEffects)');links.appendChild(button)}button.textContent='효과 '+(stageEffects?'ON':'OFF');button.setAttribute('aria-label','작은 효과 '+(stageEffects?'켜짐':'꺼짐'));button.setAttribute('aria-pressed',String(stageEffects))}}
const renderBeforeCute=render;render=function(){renderBeforeCute();syncCuteControls();if(!S||S!==cuteOwner){clearCute();cuteScene='';cuteOwner=S}if(!cuteAllowed()){clearCute();return}const event=cuteSceneEvent(S);if(!event){cuteScene='';return}if(event.key===cuteScene)return;cuteScene=event.key;if(cuteBusy)cutePending.push(event);else emitCute([event])};
const actBeforeCute=act;act=function(fn,...args){const before=cuteSnapshot(S);cuteBusy=true;cutePending=[];try{actBeforeCute(fn,...args)}finally{cuteBusy=false}const events=cuteActionEvents(fn,args,before,cuteSnapshot(S));emitCute([...events,...cutePending]);cutePending=[]};
const toggleBeforeCute=toggleStageEffects;toggleStageEffects=function(on){clearCute();toggleBeforeCute(on)};
const openKeepsakeBeforeCute=openKeepsake;openKeepsake=async function(kind){if(!S||!['poster','ticket'].includes(kind)||kind==='ticket'&&S.phase!=='result')return;await openKeepsakeBeforeCute(kind);if(kind==='ticket'&&document.querySelector('#keepsake-preview')&&keepsakeImage?.name==='lucy-island-ticket.png')emitCute([{type:'ticket',text:'오늘의 공연, 한 장에 담았다 ♡'}])};
render();
